"""SSE transport for Copilot v2: bounded sends, ping, disconnect probe.

The structure follows ``sse_starlette.EventSourceResponse`` (see that project's
ARCHITECTURE.md): concurrent tasks race, and whichever finishes first cancels
its siblings, so exactly one outcome ends the stream. Adapted to Sanic, which
exposes no ASGI ``receive()``, so a disconnect is polled off the transport
rather than awaited.

This module bounds the *transport* only. The agent's own per-event deadline is
a separate axis that lives in the runtime, which is why a ping never touches
it: it proves the socket is alive, not that the agent made progress.
Graceful shutdown, sse-starlette's fourth racer, is deliberately left out.
"""

from __future__ import annotations

import asyncio
from collections.abc import AsyncGenerator, Awaitable, Callable, Coroutine
from contextlib import aclosing
from typing import Any

import structlog

from rasa.builder import config as builder_config
from rasa.builder.copilot.exceptions import CopilotSendTimeoutException

structlogger = structlog.get_logger()

# Clients must ignore SSE comments, which is what makes this an invisible ping.
PING_FRAME = ": ping\n\n"

_DISCONNECT_POLL_INTERVAL = 1.0

SendFrame = Callable[[str], Awaitable[None]]


async def stream_events(
    frames: AsyncGenerator[str, None],
    send: SendFrame,
    is_disconnected: Callable[[], bool],
    *,
    ping_interval: float = builder_config.COPILOT_V2_PING_INTERVAL,
    send_timeout: float = builder_config.COPILOT_V2_SEND_TIMEOUT,
) -> None:
    """Write ``frames`` to the client until one of three outcomes wins.

    The racers are the producer, the ping, and the disconnect probe. Normal
    completion is the producer running out of frames; the other two exist
    so a wedged or vanished client ends the connection instead of holding it
    open. ``frames`` is closed on every path, which is what tears the agent run
    down and stops paying for tokens nobody will read.

    Raises:
        CopilotSendTimeoutException: A single frame took longer than
            ``send_timeout`` to write.
    """
    sender = BoundedSender(send, send_timeout)

    await _race(
        _stream_response(frames, sender),
        _ping(sender, ping_interval),
        _listen_for_disconnect(is_disconnected),
        teardown_timeout=send_timeout,
    )


class BoundedSender:
    """The one way a frame reaches the client: serialized and time-boxed.

    The ping and the event stream write to the same connection from different
    tasks, so routing every frame through a single owner of the lock is what
    stops two writes interleaving mid-frame and corrupting the event stream.

    Also usable outside :func:`stream_events` for writes that happen before or
    after the race (pre-flight refusals, terminal error frames), so no path to
    the client is ever an unbounded raw send.
    """

    def __init__(self, send: SendFrame, send_timeout: float) -> None:
        self._send = send
        self._send_timeout = send_timeout
        self._lock = asyncio.Lock()

    async def send(self, frame: str) -> None:
        """Write one frame, waiting out any in-flight write first.

        Raises:
            CopilotSendTimeoutException: The write did not complete in time,
                which means the client has stopped draining the stream.
        """
        async with self._lock:
            try:
                async with asyncio.timeout(self._send_timeout) as deadline:
                    await self._send(frame)
            except TimeoutError as exc:
                if not deadline.expired():
                    raise
                structlogger.warning(
                    "copilot_v2.sse.send_timed_out",
                    send_timeout=self._send_timeout,
                )
                raise CopilotSendTimeoutException(
                    f"SSE frame not written within {self._send_timeout} seconds."
                ) from exc


async def _race(
    *coroutines: Coroutine[Any, Any, None], teardown_timeout: float
) -> None:
    """Run ``coroutines`` concurrently until the first one finishes.

    sse-starlette's ``cancel_on_finish``: the winner decides the outcome for
    the whole stream and its exception, if any, is the one that propagates.
    Siblings are cancelled and awaited so none outlive the connection.

    The post-cancel await is bounded by ``teardown_timeout``: a cancelled
    producer unwinds the whole agent exit stack (generator chain, agent
    ``__aexit__``, MCP client shutdown), and any of those awaits can wedge.
    An unwind that overstays is abandoned so the request task is released.
    Holding it open is the failure mode this transport exists to prevent.
    """
    tasks = [asyncio.create_task(coroutine) for coroutine in coroutines]
    try:
        done, _ = await asyncio.wait(tasks, return_when=asyncio.FIRST_COMPLETED)
    finally:
        for task in tasks:
            task.cancel()
        try:
            async with asyncio.timeout(teardown_timeout):
                await asyncio.gather(*tasks, return_exceptions=True)
        except TimeoutError:
            structlogger.warning(
                "copilot_v2.sse.teardown_timed_out",
                teardown_timeout=teardown_timeout,
            )
    for task in done:
        task.result()


async def _stream_response(
    frames: AsyncGenerator[str, None], sender: BoundedSender
) -> None:
    """Drain ``frames`` to the client, then close the producer.

    The generator is closed here rather than by the caller so that teardown
    runs in the same task that drove it, including when this task loses the
    race and is cancelled mid-iteration.
    """
    async with aclosing(frames) as events:
        async for frame in events:
            await sender.send(frame)


async def _ping(sender: BoundedSender, ping_interval: float) -> None:
    """Emit a comment frame whenever the stream has been quiet.

    Doubles as the disconnect probe: while the agent is thinking nothing else
    writes, so this is the only thing that can notice a peer that went away.
    """
    while True:
        await asyncio.sleep(ping_interval)
        await sender.send(PING_FRAME)


async def _listen_for_disconnect(is_disconnected: Callable[[], bool]) -> None:
    """Return once the client is gone, which ends the stream.

    Sanic has no awaitable disconnect signal, so this polls the transport. It
    is a cheap hint rather than a guarantee. The ping's failing write is the
    other half of the story. A probe that cannot read the socket at all (some
    transports raise) is not evidence of a disconnect, so it fails open:
    tearing a healthy run down over an unreadable probe is the worse error.
    """
    while True:
        try:
            if is_disconnected():
                return
        except Exception as exc:
            structlogger.debug(
                "copilot_v2.sse.disconnect_probe_unavailable",
                error_type=type(exc).__name__,
            )
            break
        await asyncio.sleep(_DISCONNECT_POLL_INTERVAL)

    # An unusable probe must not end the stream, so withdraw from the race and
    # let one of the other two decide the outcome.
    await asyncio.Event().wait()
